window.OSHA_QUESTIONS_SET2 = [
  { id: "in-16", category: "intro", topic: "Mission", q: "OSHA’s mission is to:", choices: ["Collect taxes from contractors", "Assure safe and healthful working conditions for working people", "Issue building permits", "Replace workers’ compensation"], a: 1, why: "OSHA sets and enforces standards, provides training and assistance, and requires a workplace free of serious recognized hazards." },
  { id: "in-17", category: "intro", topic: "Coverage", q: "Federal OSHA generally covers:", choices: ["All public employees in every state automatically", "Most private-sector employers and their workers in states without a State Plan", "Only construction companies with 50+ employees", "Only federal agencies"], a: 1, why: "Private-sector coverage is broad. State and local government workers are covered only in State Plan states. The self-employed are generally not covered." },
  { id: "in-18", category: "intro", topic: "Not covered", q: "Which group is generally not covered by the OSH Act?", choices: ["Warehouse workers at a private distributor", "Self-employed persons with no employees", "Manufacturing plant employees", "Construction laborers on a private job"], a: 1, why: "Self-employed people, immediate family farm workers on small farms, and some workers covered by other federal agencies have limited or no OSHA coverage." },
  { id: "in-19", category: "intro", topic: "SDS access", q: "Workers have a right to:", choices: ["Safety Data Sheets and information about chemicals they work with", "The employer’s tax returns", "OSHA’s internal personnel files", "Skip hazard training"], a: 0, why: "HazCom and the OSH Act give workers access to SDS, exposure records in many cases, and their own medical records related to work." },
  { id: "in-20", category: "intro", topic: "Refuse work", q: "A worker may refuse a task when:", choices: ["They dislike the supervisor", "They have a reasonable belief of imminent death or serious injury, there is not enough time for OSHA to inspect, and they have asked the employer to correct it if possible", "Overtime is required", "PPE is the wrong color"], a: 1, why: "Refusal is a narrow right. Report the hazard, ask for correction, and do not walk off the entire job without following the criteria." },
  { id: "in-21", category: "intro", topic: "Walkaround", q: "During an OSHA inspection, a worker representative:", choices: ["Has no role", "May accompany the inspector on the walkaround", "Must stay in the office", "Can only speak if the employer agrees"], a: 1, why: "The Act provides for employee representation on the inspection walkaround." },
  { id: "in-22", category: "intro", topic: "Willful", q: "A willful violation is one committed:", choices: ["By accident with no knowledge", "With intentional disregard of, or plain indifference to, the requirements", "Only after a fatality", "Only by a worker, never an employer"], a: 1, why: "Willful citations carry the highest penalties. Repeated and failure-to-abate are other serious classifications." },
  { id: "in-23", category: "intro", topic: "Serious", q: "A serious violation exists when:", choices: ["A hazard could cause death or serious physical harm and the employer knew or should have known", "A poster is slightly crooked", "Only paperwork is late with no hazard", "A worker was rude to an inspector"], a: 0, why: "Serious = substantial probability of death or serious harm, and employer knowledge (actual or constructive)." },
  { id: "in-24", category: "intro", topic: "Poster", q: "Employers must display the OSHA Job Safety and Health poster:", choices: ["Only in the break-room freezer", "In a conspicuous place where employees can see it", "Only after a citation", "Online only, never on a wall"], a: 1, why: "The OSHA poster (or state equivalent) must be posted where workers can read it." },
  { id: "in-25", category: "intro", topic: "Abatement", q: "Abatement means:", choices: ["Paying the penalty only", "Correcting the cited hazard by the date on the citation", "Contesting every item automatically", "Firing the injured worker"], a: 1, why: "Employers must fix hazards by the abatement date or contest. Failure to abate brings extra penalties." },
  { id: "in-26", category: "intro", topic: "Multi-employer", q: "On a multi-employer construction site, OSHA may cite:", choices: ["Only the property owner", "The exposing, creating, correcting, and/or controlling employer depending on the facts", "Only the worker who got hurt", "Nobody if a GC is present"], a: 1, why: "OSHA’s multi-employer policy can place duties on more than one contractor. The controlling employer (often the GC) has a special duty to keep the site reasonably safe." },
  { id: "in-27", category: "intro", topic: "Opening conference", q: "An OSHA inspection typically begins with:", choices: ["A closing conference only", "An opening conference explaining the reason and scope", "A surprise citation with no discussion", "A medical exam of every worker"], a: 1, why: "Inspectors present credentials, explain why they are there, and outline the walkaround. A closing conference follows." },
  { id: "in-28", category: "intro", topic: "Variances", q: "An employer who cannot fully comply with a standard may apply for:", choices: ["A variance, showing equivalent protection", "A permanent exemption from all of OSHA", "A license to skip training", "A card that replaces inspections"], a: 0, why: "Temporary or permanent variances require proof of equivalent or greater protection. They are not a shortcut around safety." },
  { id: "in-29", category: "intro", topic: "11(c) filing", q: "A whistleblower complaint under Section 11(c) generally must be filed with OSHA within:", choices: ["24 hours", "30 days", "1 year", "5 years"], a: 1, why: "11(c) complaints are typically due within 30 days of the retaliatory act. Other whistleblower statutes can have different deadlines." },
  { id: "in-30", category: "intro", topic: "Consultation", q: "OSHA On-Site Consultation:", choices: ["Issues citations the same as enforcement", "Is a free, confidential program for small and medium employers that does not issue citations", "Is only for unions", "Replaces the need for an OSHA 10 card"], a: 1, why: "Consultation is separate from enforcement. Employers must correct serious hazards that consultants identify." },

  { id: "ff-08", category: "focusFour", topic: "Fall example", q: "Which is a fall-from-elevation hazard?", choices: ["An unguarded roof edge 12 feet above grade", "A pallet jack on a warehouse floor at grade with no drop", "A properly guarded 30-inch dock with a chain", "Sitting in a chair"], a: 0, why: "Unprotected sides and edges 6 feet or more in construction require fall protection." },
  { id: "ff-09", category: "focusFour", topic: "Struck-by vehicle", q: "A worker in a roadway work zone is most at risk of:", choices: ["Struck-by from public or construction vehicles", "Caught-in a filing cabinet", "Office paper cuts", "Ladder electrocution only"], a: 0, why: "High-visibility apparel, spotters, barriers, and traffic control reduce struck-by in work zones." },
  { id: "ff-10", category: "focusFour", topic: "Flying object", q: "Powder-actuated tools and grinders can create:", choices: ["Only noise, never projectiles", "Struck-by from flying fasteners or fragments", "Trench cave-ins", "Heat stress only"], a: 1, why: "Use the right load, shields, eye/face protection, and never fire toward people." },
  { id: "ff-11", category: "focusFour", topic: "Caught-in machine", q: "Unguarded rotating parts, in-running nip points, and conveyors are primarily:", choices: ["Fall hazards", "Caught-in/between hazards", "Chemical hazards", "Radiation hazards"], a: 1, why: "Lockout, guards, and keeping body parts out of the point of operation prevent crush and entanglement deaths." },
  { id: "ff-12", category: "focusFour", topic: "Trench caught-in", q: "A worker in an unprotected 7-foot trench is exposed to:", choices: ["Caught-in/between from cave-in", "Only struck-by from tools", "Only noise", "No Focus Four hazard"], a: 0, why: "Soil is heavy. A cubic yard can weigh more than a car. Protective systems are not optional." },
  { id: "ff-13", category: "focusFour", topic: "Overhead load", q: "Walking under a suspended load is:", choices: ["Acceptable if you walk fast", "A struck-by (and crushing) hazard that is prohibited", "Required to guide the load", "Safe with a hard hat only"], a: 1, why: "Hard hats do not stop a steel beam. Stay out of the fall zone." },
  { id: "ff-14", category: "focusFour", topic: "Overhead lines", q: "Raising a ladder or boom near an overhead line is mainly an:", choices: ["Caught-in hazard", "Electrocution hazard", "Silica hazard", "Noise hazard"], a: 1, why: "Maintain 10-foot (or greater) clearance, use spotters, and consider de-energizing lines." },
  { id: "ff-15", category: "focusFour", topic: "GFCI", q: "GFCI protection on temporary construction power primarily reduces:", choices: ["Falls", "Electrocution and shock", "Heat illness", "Cave-ins"], a: 1, why: "GFCIs trip on small ground-fault current before a lethal shock in many cases. They do not replace insulation or lockout." },
  { id: "ff-16", category: "focusFour", topic: "Prevention falls", q: "The preferred construction control for a roof edge is:", choices: ["Hope workers remember to tie off", "A guardrail or other conventional system that protects everyone", "A memo", "Painting the edge yellow only"], a: 1, why: "Engineering controls (guardrails) protect even if someone forgets a harness." },
  { id: "ff-17", category: "focusFour", topic: "Drop zone", q: "To reduce falling-object struck-by hazards:", choices: ["Toeboards, debris nets, canopies, and keeping people out of the drop zone", "Hard hats only with no other controls", "Working at night", "Faster demolition"], a: 0, why: "1926.501/502: falling-object protection plus barricades below." },

  { id: "fp-17", category: "fallProtection", topic: "Leading edge", q: "A leading edge is:", choices: ["The edge of a floor, roof, or formwork that changes location as new sections are placed", "Any wall", "A finished parapet", "A stair nosing only"], a: 0, why: "Leading-edge work is a high-fall-risk activity. Conventional protection or a documented alternative is required at 6 feet." },
  { id: "fp-18", category: "fallProtection", topic: "Residential", q: "For residential construction, OSHA currently expects:", choices: ["No fall protection under 15 feet", "Conventional fall protection at 6 feet unless a valid alternative under Subpart M is used", "Only slide guards forever as the sole system", "Body belts for arrest"], a: 1, why: "OSHA cancelled the old residential directive that allowed more alternatives. 6-foot conventional protection is the baseline." },
  { id: "fp-19", category: "fallProtection", topic: "Midrail", q: "If there is no wall at least 21 inches high, a guardrail system needs a midrail approximately:", choices: ["Halfway between the top rail and the walking surface", "At 6 inches", "At 60 inches", "Only on scaffolds"], a: 0, why: "Midrails are about 21 inches when the top rail is 42. Screens or intermediate members can substitute if they meet the standard." },
  { id: "fp-20", category: "fallProtection", topic: "Steel cable rails", q: "Flagging on a wire-rope guardrail is used to:", choices: ["Increase strength to 5,000 lb", "Make the rail more visible", "Replace the need for a top rail", "Ground the system"], a: 1, why: "High-visibility flagging at least every 6 feet is required on wire-rope rails so people see the edge." },
  { id: "fp-21", category: "fallProtection", topic: "Lanyard", q: "A shock-absorbing lanyard is designed to:", choices: ["Eliminate all fall distance", "Reduce arresting force on the body", "Replace an anchorage", "Be tied around a guardrail as the preferred anchorage always"], a: 1, why: "Know deceleration distance. Allow enough clearance so you do not hit the level below." },
  { id: "fp-22", category: "fallProtection", topic: "Clearance", q: "Before using PFAS you must calculate:", choices: ["Only the cost of the harness", "Fall clearance: free fall + deceleration + height of worker + safety margin vs the level below", "Only the roof pitch", "Wind speed only"], a: 1, why: "A 6-foot lanyard can need about 18+ feet of clearance with shock pack, harness stretch, and D-ring height. SRLs change the math." },
  { id: "fp-23", category: "fallProtection", topic: "SRL", q: "A self-retracting lifeline (SRL) generally:", choices: ["Allows a 30-foot free fall", "Locks quickly to limit free fall, often to 2 feet or less depending on the unit", "Replaces the need to inspect", "May be wrapped over a sharp edge with no leading-edge rating"], a: 1, why: "Use SRLs rated for the application (including leading edge). Inspect and follow the manufacturer." },
  { id: "fp-24", category: "fallProtection", topic: "Rescue", q: "After a fall arrest, the employer must have:", choices: ["No plan; 911 is always enough by itself", "A prompt rescue plan — suspension trauma can kill", "A plan only for roofs over 50 feet", "Workers cut themselves down"], a: 1, why: "1926.502(d)(20): prompt rescue. Do not leave a worker hanging. Train and stage retrieval." },
  { id: "fp-25", category: "fallProtection", topic: "Skylights", q: "Skylights are treated as:", choices: ["Decorations, not holes", "Holes that must be guarded or covered; people fall through them", "Safe to walk on if they look thick", "Exempt under 15 feet"], a: 1, why: "Unguarded skylights are a classic fatality. Screen, cover, or guardrail them." },
  { id: "fp-26", category: "fallProtection", topic: "Wall openings", q: "Wall openings from which there is a drop of more than 6 feet and the opening is at least 30 inches high and 18 inches wide generally need:", choices: ["Nothing", "Guardrail protection", "Only caution tape", "A sign 100 feet away"], a: 1, why: "1926.501(b)(14): protect wall openings. Window openings during construction are included." },
  { id: "fp-27", category: "fallProtection", topic: "Ramps", q: "Ramps and runways 6 feet or more above a lower level need:", choices: ["Fall protection such as guardrails", "Only non-slip paint", "Nothing if used by wheelbarrows", "A 2x4 on one side"], a: 0, why: "1926.501(b)(5): ramps, runways, and other walkways require protection at 6 feet." },
  { id: "fp-28", category: "fallProtection", topic: "Hoist areas", q: "At a hoist area, employees must be protected from:", choices: ["Only noise", "Falling and from being struck by objects; guardrail can have a removable chain/gate during landing", "Nothing during material landing", "Only weather"], a: 1, why: "1926.502(b)(3) and 501(b)(3): protect the edge. Chains must meet guardrail strength when closed." },
  { id: "fp-29", category: "fallProtection", topic: "Overhand bricklaying", q: "A controlled access zone for overhand bricklaying uses a control line generally:", choices: ["3 feet from the edge", "10 to 15 feet from the working edge", "50 feet from the edge", "At grade only"], a: 1, why: "1926.502(k): 10–15 feet, with access limited to masons. It is an alternative system with strict limits, not a free-for-all." },
  { id: "fp-30", category: "fallProtection", topic: "Compatible connectors", q: "Snap hooks and D-rings must be:", choices: ["Any hardware from the gang box", "Compatible; double-locking snaphooks; not connected back to the lanyard except as designed", "Tied in knots", "Two hooks in one D-ring always"], a: 1, why: "1926.502(d): incompatible connections can roll-out. Follow the manufacturer." },
  { id: "fp-31", category: "fallProtection", topic: "After a fall", q: "A harness or lanyard that has arrested a fall must be:", choices: ["Reused after a visual glance", "Removed from service", "Washed and returned the same day always", "Used as a positioning belt"], a: 1, why: "Energy-absorbing packs and webbing are one-time arrest devices unless the manufacturer says otherwise after inspection by a competent person." },
  { id: "fp-32", category: "fallProtection", topic: "Anchor improvise", q: "Which is a poor anchorage?", choices: ["A designed 5,000-lb roof anchor", "A 2x4 fascia, standard guardrail, or PVC pipe", "A structural steel member rated by a qualified person", "An engineered davit"], a: 1, why: "Never tie off to a guardrail, conduit, or something that will fail or cut the lanyard. Anchorage must meet 502(d)(15)." },
  { id: "fp-33", category: "fallProtection", topic: "Positioning", q: "A positioning device system must prevent a free fall of more than:", choices: ["6 feet", "2 feet", "12 feet", "30 feet"], a: 1, why: "1926.502(e): positioning limits free fall to 2 feet. It is not a substitute for fall arrest when you can fall off the work." },
  { id: "fp-34", category: "fallProtection", topic: "Vertical lifeline", q: "Each employee on a vertical lifeline generally needs:", choices: ["To share one rope grab with a partner", "Their own independent lifeline", "No rope grab", "A body belt"], a: 1, why: "1926.502(d)(10): one person per vertical lifeline unless the system is designed otherwise." },
  { id: "fp-35", category: "fallProtection", topic: "Horizontal lifeline", q: "Horizontal lifelines must be designed by:", choices: ["Any foreman", "A qualified person, with a safety factor of at least two", "The newest apprentice", "OSHA during the inspection"], a: 1, why: "Sag, span, and number of users change forces dramatically. This is not a hardware-store project." },
  { id: "fp-36", category: "fallProtection", topic: "Steep roof", q: "On a steep roof (slope greater than 4:12), warning lines:", choices: ["Are a complete substitute for conventional protection", "Are not the system used for steep roofs — use conventional protection (guardrails, nets, or PFAS)", "Are required at 3 feet", "Replace toe boards"], a: 1, why: "Warning line systems in 502(f) are for low-slope roofing. Steep roofs need conventional systems." },

  { id: "ld-13", category: "ladders", topic: "Rung spacing", q: "Fixed and portable ladder rungs are generally spaced between:", choices: ["4 and 6 inches", "10 and 14 inches", "18 and 24 inches", "30 and 36 inches"], a: 1, why: "1926.1053(a)(3): 10–14 inches. Uniform spacing is required." },
  { id: "ld-14", category: "ladders", topic: "Duty rating", q: "A ladder’s duty rating must be:", choices: ["Ignored if you climb slowly", "At least the combined weight of the user plus tools and materials", "Only for the empty ladder", "Half the user’s weight"], a: 1, why: "Type IAA, IA, I, II, III ratings are manufacturer/ANSI. OSHA requires not exceeding capacity." },
  { id: "ld-15", category: "ladders", topic: "Face ladder", q: "When climbing a ladder you should:", choices: ["Face the ladder", "Face away and slide", "Skip rungs to go faster", "Carry a sheet of plywood in both hands"], a: 0, why: "Face the ladder, use three-point contact, and hoist materials with a line if needed." },
  { id: "ld-16", category: "ladders", topic: "Top step extension", q: "The top step of an extension ladder should:", choices: ["Be stood on like a platform", "Not be used as a step; stay below the manufacturer’s limit", "Be the preferred work position", "Hold two workers"], a: 1, why: "Do not stand on the top cap of a stepladder or the top rungs of an extension ladder beyond the label." },
  { id: "ld-17", category: "ladders", topic: "Secure", q: "Ladders should be:", choices: ["Placed on boxes to gain height", "On stable, level footing and secured when used in ways that could displace them", "Leaned on a stack of barrels", "Painted to hide defects"], a: 1, why: "1926.1053(b): firm level ground, not on unstable objects. Secure the top or have someone hold the base when needed." },
  { id: "ld-18", category: "ladders", topic: "Job-made", q: "Job-made ladders must:", choices: ["Use any scrap lumber", "Meet 1926.1053 construction requirements (cleats, filler, through-dado, etc.)", "Be metal only", "Have rungs 24 inches apart"], a: 1, why: "Job-made ladders are allowed if built to the standard. Nail-on rungs without filler blocks fail." },
  { id: "ld-19", category: "ladders", topic: "Door swing", q: "If a ladder is placed in front of a door:", choices: ["It is always fine", "The door must be blocked open, locked, or guarded so it cannot strike the ladder", "A note on the door is enough", "Only cones are required"], a: 1, why: "A swinging door knocks people off ladders. Control the door." },
  { id: "ld-20", category: "ladders", topic: "Scaffold access", q: "Access to scaffold platforms more than 2 feet above or below the point of access generally requires:", choices: ["Jumping", "A ladder, stair tower, ramp, or equivalent — not climbing braces", "Climbing the cross-braces", "A rope only"], a: 1, why: "1926.451(e): proper access. Do not climb end frames unless they are designed as ladders." },
  { id: "ld-21", category: "ladders", topic: "Mud sills", q: "Scaffold legs on soil should rest on:", choices: ["Soft dirt only", "Base plates and mud sills or other adequate firm foundation", "A single brick", "Cinder blocks on their side as a habit"], a: 1, why: "1926.451(c)(2): base plates and adequate sills. Unstable footings cause collapses." },
  { id: "ld-22", category: "ladders", topic: "Light duty", q: "A light-duty scaffold is generally rated for:", choices: ["25 psf", "50 psf", "75 psf", "Unlimited load"], a: 0, why: "1926.451: light 25, medium 50, heavy 75 pounds per square foot. Do not overload with masonry pallets on a light-duty frame." },
  { id: "ld-23", category: "ladders", topic: "Toeboards scaffold", q: "Toeboards are required on scaffolds when:", choices: ["Never", "Employees work or pass below and falling-object protection is needed, generally at 10 feet and as specified", "Only over 50 feet", "Only on rolling towers"], a: 1, why: "1926.451(h): falling-object protection — toeboards, screens, debris nets, or canopy, plus barricades below." },
  { id: "ld-24", category: "ladders", topic: "Rolling tower", q: "Before moving a rolling scaffold (mobile tower):", choices: ["Keep workers on the platform to save time", "Remove or secure materials; workers generally should not ride unless the scaffold is designed for it", "Leave casters unlocked", "Push as fast as possible"], a: 1, why: "1926.452(w): lock casters when parked, level, do not ride unless allowed, height-to-base limits." },
  { id: "ld-25", category: "ladders", topic: "Power lines scaffold", q: "Scaffolds near energized lines must maintain:", choices: ["No clearance if wood", "Specified clearances (often 10 feet for up to 50 kV) or have lines de-energized/relocated/insulated", "3 feet", "Contact is OK with rubber boots"], a: 1, why: "1926.451(f)(6): distance from lines. Insulated lines still need the required approach distance unless qualified." },
  { id: "ld-26", category: "ladders", topic: "Competent scaffold", q: "A scaffold competent person is someone who:", choices: ["Has a business card", "Can identify hazards and has authority to take corrective measures", "Only reads the brochure", "Is the tallest worker"], a: 1, why: "1926.32(f) definition. They inspect, train as required, and stop unsafe work." },
  { id: "ld-27", category: "ladders", topic: "Two-point swing", q: "Two-point suspension scaffolds (swing stages) require:", choices: ["No fall protection if over water", "Fall protection (typically PFAS independent of the scaffold) and proper tieback of counterweights/outriggers", "Only a hard hat", "Manila rope of any age"], a: 1, why: "1926.451(g)(1) and 1926.452(o): independent lifelines, rated equipment, and tiebacks. Counterweights must be designed and not made of loose sand." },

  { id: "ex-11", category: "excavation", topic: "Cave-in weight", q: "A cubic yard of soil can weigh roughly:", choices: ["50 pounds", "As much as a small car (about 3,000 pounds or more depending on soil and moisture)", "5 pounds", "The same as styrofoam"], a: 1, why: "That is why a collapse buries and crushes. You cannot dig someone out by hand in time." },
  { id: "ex-12", category: "excavation", topic: "Type A", q: "Type A soil is:", choices: ["The least stable", "Cohesive soil with unconfined compressive strength of 1.5 tsf or greater, with no fissures, vibration, or previous disturbance (and other Type A limits)", "Always sand", "Always Type C after rain"], a: 1, why: "Type A cannot be layered over B/C in a way that fails, and cannot be previously disturbed. Many jobsites do not actually have Type A." },
  { id: "ex-13", category: "excavation", topic: "Type B", q: "Type B soil is generally sloped no steeper than:", choices: ["3/4 : 1", "1 : 1 (45 degrees) for simple slope under 20 feet", "1.5 : 1", "Vertical"], a: 1, why: "Appendix B tabulated data. Angular gravel and silt often classify as B or C." },
  { id: "ex-14", category: "excavation", topic: "Shield vs shore", q: "A trench shield (trench box):", choices: ["Supports the soil like hydraulic shores in all cases", "Protects workers inside the box; it does not prevent a cave-in outside the box", "Lets you work above the box top without protection", "Replaces the need for a competent person"], a: 1, why: "Stay inside the shield. Do not work outside the ends. Tabulated data and manufacturer depth ratings apply." },
  { id: "ex-15", category: "excavation", topic: "Box height", q: "The top of a trench box should extend:", choices: ["At least 18 inches above the surrounding soil if there is a chance of sloughing into the box, per manufacturer/tabulated data practice", "2 inches below grade always", "Flush and never above", "10 feet above"], a: 0, why: "Manufacturers typically require the box to extend above the trench lip so spoil cannot bury workers. Follow the tabulated data." },
  { id: "ex-16", category: "excavation", topic: "Ladder in trench", q: "A ladder used for trench egress must:", choices: ["Be within 25 feet of workers and extend above the landing as required", "Be laid on the spoil pile", "Be aluminum next to services always", "Be optional at 6 feet"], a: 0, why: "Combine 1926.651(c)(2) with ladder rules: 3-foot extension, secured, proper angle." },
  { id: "ex-17", category: "excavation", topic: "Vibration", q: "Heavy equipment or traffic near a trench:", choices: ["Improves soil strength", "Can reduce soil stability; the competent person must evaluate", "Is required for compaction of walls", "Means Type A automatically"], a: 1, why: "Vibration can change classification and require more protection or setbacks." },
  { id: "ex-18", category: "excavation", topic: "Surcharge", q: "Spoil piles, equipment, and materials near the edge create:", choices: ["A surcharge load that can trigger collapse", "Extra protection", "Type A soil", "A means of egress"], a: 0, why: "Keep 2 feet back minimum and consider more distance for heavy equipment. Use retaining devices if closer." },
  { id: "ex-19", category: "excavation", topic: "After rain", q: "After a rainstorm, excavations must be:", choices: ["Entered immediately to pump by hand", "Re-inspected by a competent person before workers re-enter", "Assumed safer because soil is packed", "Exempt from sloping"], a: 1, why: "1926.651(k)(1): inspect after every hazard-increasing occurrence, including rain." },
  { id: "ex-20", category: "excavation", topic: "Hazardous atmosphere", q: "Excavations near sewers, landfills, or tanks may have:", choices: ["Only extra oxygen", "Oxygen deficiency, flammable gas, or toxic atmospheres (H2S, CO, etc.)", "No atmospheric risk below 20 feet", "Only dust"], a: 1, why: "Test at 4 feet and as needed. Ventilate. Emergency rescue must be considered." },
  { id: "ex-21", category: "excavation", topic: "Water removal", q: "If water removal equipment is used, it must be:", choices: ["Unattended always", "Monitored by a competent person", "Gasoline-powered in the hole without ventilation", "Optional documentation"], a: 1, why: "1926.651(h)(2): competent person monitors water removal to protect employees." },
  { id: "ex-22", category: "excavation", topic: "Ramp", q: "A structural ramp used for access/egress must be:", choices: ["Designed by a competent person (and PE if for vehicles, as specified)", "Any dirt slope", "Steeper than 45 degrees always", "Made of wet plywood only"], a: 0, why: "1926.651(c)(1): ramps and runways designed by a competent person; vehicle ramps by a PE." },

  { id: "el-11", category: "electrical", topic: "Over 50 kV", q: "For overhead lines over 50 kV, the 10-foot clearance generally increases by:", choices: ["1 inch for every extra volt", "4 inches for every 10 kV over 50 kV", "10 feet for every kV", "No increase is required"], a: 1, why: "1910.333(c)(3) / 1926.416: 10 ft + 4 in per 10 kV over 50 kV for unqualified persons." },
  { id: "el-12", category: "electrical", topic: "AEGCP", q: "An Assured Equipment Grounding Conductor Program requires:", choices: ["No testing", "Written procedures and specified tests of cords and receptacles (including periodic continuity tests)", "Only a GFCI sticker", "Testing once per decade"], a: 1, why: "1926.404(b)(1)(iii): AEGCP is the alternative to GFCI. Most sites simply use GFCI." },
  { id: "el-13", category: "electrical", topic: "Double insulated", q: "A double-insulated tool:", choices: ["Needs a three-prong plug", "Is marked and may use a two-wire cord; the insulating system replaces the equipment ground", "Can be used with a damaged housing", "Never needs GFCI on a construction site"], a: 1, why: "Look for the box-within-a-box mark. Housing damage destroys the protection. Construction still often requires GFCI on the receptacle." },
  { id: "el-14", category: "electrical", topic: "Extension cords", q: "Flexible cords on construction sites must be:", choices: ["Stapled to wood with roofing nails", "Hard-service type, not worn, and not used as a substitute for fixed wiring", "Two-wire zip cord from a lamp", "Passed through doorways so the door pinches them"], a: 1, why: "1926.405/416: strain relief, no damage, proper type (S, ST, SO, etc.). Do not hang by the wire or run through windows that cut insulation." },
  { id: "el-15", category: "electrical", topic: "Wet GFCI", q: "In wet locations, portable lighting and tools should be:", choices: ["Ungrounded always", "GFCI-protected and listed for the environment", "Wired with lamp cord", "Left on overnight in standing water"], a: 1, why: "Water plus electricity is a killer. Use wet-location listings and GFCI." },
  { id: "el-16", category: "electrical", topic: "Arc flash", q: "An arc flash can:", choices: ["Only tingle", "Produce extreme heat, pressure, and burns even without contacting a conductor", "Happen only above 15 kV", "Be stopped by cotton clothing alone always"], a: 1, why: "Qualified persons use NFPA 70E-style practices, FR clothing, and de-energizing. OSHA 1910.269/333 address related hazards." },
  { id: "el-17", category: "electrical", topic: "Temporary lights", q: "Temporary lamps must be:", choices: ["Bare bulbs that workers can touch", "Protected from contact and breakage (cages/guards)", "Wired with doorbell wire", "Hung by the cord as the listed method always"], a: 1, why: "1926.405(a)(2)(ii): guards on temporary lights. Do not suspend by the cord unless designed for it." },
  { id: "el-18", category: "electrical", topic: "Strain relief", q: "Cords must have strain relief so that:", choices: ["The plug looks neat", "Tension is not transmitted to the joints or terminals", "The ground pin breaks first", "GFCI never trips"], a: 1, why: "Pulled connections expose conductors. Use proper cord caps." },
  { id: "el-19", category: "electrical", topic: "Overcurrent", q: "Fuses and circuit breakers are meant to:", choices: ["Protect the conductor and equipment from overcurrent", "Increase voltage", "Replace grounding", "Serve as lockout devices without a lock"], a: 0, why: "They are not a substitute for LOTO. Turning a breaker off is not lockout unless it is locked and verified." },
  { id: "el-20", category: "electrical", topic: "Wet concrete", q: "Working with electrical tools while standing in water or on wet concrete:", choices: ["Is low risk because concrete insulates", "Increases shock severity because you are well grounded", "Is required for GFCI testing", "Only matters for 12-volt tools"], a: 1, why: "Concrete, earth, and water provide a ground path. Use GFCI and dry standing places." },
  { id: "el-21", category: "electrical", topic: "Bonding", q: "The equipment grounding conductor must be:", choices: ["Cut to save time", "Continuous and connected so enclosures and tool frames cannot become energized undetected", "The white wire", "Optional on metal boxes"], a: 1, why: "A missing ground is a shock waiting for a fault. Test cords in an AEGCP or replace damaged gear." },
  { id: "el-22", category: "electrical", topic: "Approach", q: "Unqualified workers must not approach closer than the required distance to:", choices: ["De-energized, locked, tagged, and tested circuits", "Exposed energized parts", "Battery-powered drills", "Fiber-optic cable"], a: 1, why: "Stay back. Only qualified persons with proper PPE and procedures work near live parts." },
  { id: "el-23", category: "electrical", topic: "Generator GFCI", q: "Portable generators used on construction for 120-volt tools:", choices: ["Never need GFCI", "Often require GFCI on 15/20-amp receptacles under the construction electrical standard", "Should be used in a closed room for quiet", "Should be bonded to a fire hydrant only"], a: 1, why: "Follow 1926.404 and manufacturer instructions. Exhaust is a CO killer indoors." },
  { id: "el-24", category: "electrical", topic: "Water and electricity", q: "If a coworker is being shocked and still in contact with the source, you should:", choices: ["Grab them with bare hands", "De-energize or separate them with an insulated object; do not become a second victim", "Pour water on them", "Pull the wire with your hand"], a: 1, why: "Shut off power first if you can. Call emergency services. CPR if trained once it is safe." },
  { id: "el-25", category: "electrical", topic: "Marking", q: "Electrical equipment must be marked with:", choices: ["The superintendent’s nickname", "Manufacturer, voltage, current, and other ratings as required", "Only a QR code", "Nothing if painted"], a: 1, why: "1910.303(e) / 1926.403: markings. Use equipment within its listing and rating." },

  { id: "pp-16", category: "ppe", topic: "Foot", q: "Safety-toe footwear is typically selected to:", choices: ["ANSI/ASTM impact and compression ratings for the hazard", "Fashion only", "The cheapest steel regardless of fit", "Open-toe for ventilation"], a: 0, why: "Match the hazard: impact, compression, puncture, electrical hazard (EH), and chemical." },
  { id: "pp-17", category: "ppe", topic: "Class E hat", q: "A Class E hard hat is intended for:", choices: ["No electrical protection", "Electrical insulation up to 20,000 volts (utility-style electrical class)", "Welding only", "Molten metal only"], a: 1, why: "Z89.1: Class G (2,200 V), Class E (20,000 V), Class C (conductive, no electrical). Electrical ratings are for the hat, not live-line work by themselves." },
  { id: "pp-18", category: "ppe", topic: "Side shields", q: "When flying particles are present, eye protection must:", choices: ["Be worn with side protection", "Be tinted fashion glasses", "Be optional over contacts", "Be a face shield only with no spectacles"], a: 0, why: "Side shields or wraparound Z87. Face shields are in addition to, not instead of, primary eye protection for many tasks." },
  { id: "pp-19", category: "ppe", topic: "Welding filter", q: "Welding filter shade is selected based on:", choices: ["The process and current (shade numbers on OSHA/ANSI charts)", "Darkest available always", "No filter if you squint", "Clear lenses for TIG only"], a: 0, why: "1926.102 / 1910.133 tables list shades. Too light causes burns; too dark hides the puddle and causes poor work/unsafe posture." },
  { id: "pp-20", category: "ppe", topic: "Hearing NRR", q: "NRR on hearing protectors is:", choices: ["A laboratory rating; real-world protection is often less, and OSHA has a derating method", "Guaranteed field dB reduction for everyone", "The noise PEL", "Only for musicians"], a: 0, why: "Fit matters. OSHA 1910.95 Appendix B derates NRR. Double protection (plugs + muffs) adds limited extra reduction." },
  { id: "pp-21", category: "ppe", topic: "APF", q: "Assigned Protection Factor (APF) for a half-mask respirator with filters is generally:", choices: ["5", "10", "50", "1,000"], a: 1, why: "1910.134 Table 1: half-mask APF 10, full-face 50, PAPR half 50, tight-fitting PAPR full-face 1,000, etc. Fit testing is still required for tight-fitting." },
  { id: "pp-22", category: "ppe", topic: "IDLH", q: "In IDLH atmospheres, OSHA generally requires:", choices: ["A dust mask", "Full-face pressure-demand SCBA or combination SAR with auxiliary escape SCBA, and a standby person", "Any N95", "Voluntary use only"], a: 1, why: "1910.134(d)(2) and (g)(3): IDLH needs the highest respiratory protection and rescue capability." },
  { id: "pp-23", category: "ppe", topic: "High-vis class", q: "ANSI/ISEA 107 high-visibility classes (1, 2, 3) relate to:", choices: ["How much background fluorescent material and retroreflective tape you need for the speed/complexity of traffic", "Hard-hat color only", "Flame resistance only", "Fall-arrest rating"], a: 0, why: "Roadway work often requires Class 2 or 3. Follow MUTCD and the contract." },
  { id: "pp-24", category: "ppe", topic: "Gloves cut", q: "Cut-resistant gloves are rated by:", choices: ["ANSI/ISEA 105 cut levels (A1–A9) or equivalent", "Color only", "Thickness of cotton", "Whether they are leather"], a: 0, why: "Match the blade and task. Cut gloves may not be puncture- or chemical-resistant." },
  { id: "pp-25", category: "ppe", topic: "Retrain PPE", q: "Retraining on PPE is required when:", choices: ["The worker shows they do not understand, or workplace/PPE changes", "Never after initial training", "Only if OSHA visits", "Every hour"], a: 0, why: "1910.132(f)(3): changes in workplace, PPE, or demonstrated lack of knowledge." },
  { id: "pp-26", category: "ppe", topic: "Prescription", q: "Workers who wear prescription glasses in impact areas need:", choices: ["Street glasses only", "Z87 prescription safety glasses or goggles/covers that fit over them", "Contacts only", "No protection if they have glasses"], a: 1, why: "Fashion glasses are not safety glasses. Side protection still applies." },
  { id: "pp-27", category: "ppe", topic: "Harness fit", q: "A full-body harness should be adjusted so that:", choices: ["D-ring is between the shoulder blades and straps are snug without cutting circulation", "It hangs loose for comfort", "The D-ring is on the chest for all arrest applications", "Chest strap is omitted"], a: 0, why: "Dorsal D-ring for arrest. Sub-pelvic strap positioned correctly. Follow the manufacturer." },

  { id: "hc-11", category: "hazcom", topic: "Label elements", q: "A shipped-container GHS label must include:", choices: ["Product identifier, signal word, hazard statements, pictograms, precautionary statements, and supplier identification", "Only a SKU barcode", "A skull if the chemical smells strong", "The OSHA poster"], a: 0, why: "1910.1200(f). Workplace labels can use alternative systems if they convey the required information." },
  { id: "hc-12", category: "hazcom", topic: "Pictogram health", q: "The health-hazard pictogram (silhouette with a starburst on the chest) covers:", choices: ["Carcinogens, mutagens, reproductive toxins, respiratory sensitizers, target-organ and aspiration hazards", "Only flammability", "Compressed gases", "Only skin corrosion"], a: 0, why: "Corrosion pictogram is for skin/eye damage and metal corrosion. Skull is acute toxicity." },
  { id: "hc-13", category: "hazcom", topic: "Flame over circle", q: "The flame-over-circle pictogram means:", choices: ["Oxidizer", "Explosive", "Compressed gas", "Irritant"], a: 0, why: "Oxidizers give off oxygen and intensify fire. Keep them away from fuels." },
  { id: "hc-14", category: "hazcom", topic: "Exclamation", q: "The exclamation-mark pictogram can indicate:", choices: ["Irritant, skin sensitizer, acute toxicity (harmful), narcotic effects, or respiratory tract irritation", "Always a carcinogen", "Always an explosive", "No hazard"], a: 0, why: "It is the “less severe” acute pictogram compared with the skull." },
  { id: "hc-15", category: "hazcom", topic: "Section 8", q: "SDS Section 8 typically covers:", choices: ["First aid", "Exposure controls and personal protection, including OELs", "Transport UN numbers only", "Ecological information only"], a: 1, why: "Use Section 8 with Section 2 and 4. PEL/TLV values may be listed; your site may need lower internal limits." },
  { id: "hc-16", category: "hazcom", topic: "Section 4", q: "SDS Section 4 is:", choices: ["First-aid measures", "Firefighting", "Stability", "Disposal"], a: 0, why: "Know first aid before you use the chemical, not after the splash." },
  { id: "hc-17", category: "hazcom", topic: "Trade secret", q: "Chemical identity claimed as a trade secret:", choices: ["Means no SDS is required", "Must still disclose hazards; identity is available to health professionals in emergencies as specified", "Lets the employer skip labels", "Applies only to water"], a: 1, why: "1910.1200(i): trade secrets have limits. Emergency medical personnel can get the identity." },
  { id: "hc-18", category: "hazcom", topic: "Non-English", q: "HazCom information must be presented:", choices: ["Only in English even if nobody understands it", "In a language and manner workers understand, with English SDS still required in the U.S.", "Only as pictograms with no training", "Via text message only"], a: 1, why: "Training must be comprehensible. OSHA requires English SDS; other languages can be added." },
  { id: "hc-19", category: "hazcom", topic: "Pipes", q: "Unlabeled pipes in a workplace:", choices: ["Are exempt from any information duty", "Must be addressed in the written program (for example, by signs, process diagrams, or procedures)", "Always contain water", "Need GHS diamonds every 3 feet by federal rule in all plants"], a: 1, why: "1910.1200(f)(6): the employer’s program must ensure workers know pipe contents and hazards." },
  { id: "hc-20", category: "hazcom", topic: "Consumer products", q: "Consumer products used as in a household (same duration/frequency) may be:", choices: ["Always fully labeled with GHS workplace labels anyway", "Exempt from some HazCom requirements if used as a typical consumer would", "Banned on jobsites", "Required to have 16-section SDS posted on the bottle"], a: 1, why: "The consumer-product exemption is narrow. Industrial use of the same product (more often, more volume) brings full HazCom back." },
  { id: "hc-21", category: "hazcom", topic: "Inventory update", q: "When a new hazardous chemical arrives:", choices: ["Add SDS and train as needed before workers are exposed", "Wait a year", "Hide the SDS", "Skip labels if the drum is obvious"], a: 0, why: "Keep the inventory and SDS library current. Train on new hazards." },
  { id: "hc-22", category: "hazcom", topic: "QR codes", q: "A QR code on a workplace label:", choices: ["Can supplement but must not be the only way to get required information if workers cannot access it", "Replaces all pictograms always", "Is required by OSHA on every bottle", "Means the chemical is non-hazardous"], a: 0, why: "Labels must work when phones and networks fail. Immediate visual information still matters." },

  { id: "lo-11", category: "loto", topic: "Energy types", q: "Which is a source of hazardous energy under LOTO?", choices: ["Only 480-volt electricity", "Electrical, mechanical, hydraulic, pneumatic, chemical, thermal, gravity, and radiation as applicable", "Only steam", "Only natural gas"], a: 1, why: "Think about everything that can move, flow, fall, or burn you when released." },
  { id: "lo-12", category: "loto", topic: "Procedure", q: "Machine-specific LOTO procedures are required unless:", choices: ["The employer never writes anything", "The limited exception in 1910.147(c)(4)(i) is met (single source, readily identified, etc.)", "The machine is new", "Only tags are used"], a: 1, why: "Complex or multi-source machines need written, machine-specific steps: notify, shut down, isolate, lock, relieve, verify." },
  { id: "lo-13", category: "loto", topic: "Tagout only", q: "Tagout without a lock is allowed only when:", choices: ["The employer prefers tags", "The energy-isolating device cannot accept a lock, and full tagout provisions (including extra training and equivalent protection) are met", "It is faster", "The tag is red"], a: 1, why: "1910.147(c)(3): lockout is preferred. Tags are warnings, not physical restraints." },
  { id: "lo-14", category: "loto", topic: "Device", q: "A lockout device must be:", choices: ["Standardized, identifiable, and used only for energy control", "Any padlock from home", "The same as a tool-crib lock", "Left unlocked with the key in it"], a: 0, why: "Color, shape, or size should make LOTO locks obvious. One key per lock in the authorized employee’s control." },
  { id: "lo-15", category: "loto", topic: "Shift change", q: "During shift or personnel changes, LOTO must:", choices: ["Leave the machine unlocked between shifts", "Ensure continuity of protection — typically the incoming authorized employee applies their lock before the outgoing lock is removed", "Let production start with tags only", "Skip verification"], a: 1, why: "1910.147(e)(4): specific shift-change procedures. Never a gap with zero locks." },
  { id: "lo-16", category: "loto", topic: "Testing machine", q: "If you must temporarily energize for testing:", choices: ["Leave all locks on and hope", "Clear the machine, remove locks per procedure, energize, test, then de-energize and reapply LOTO before servicing continues", "Bypass guards forever", "Have an affected employee start it from the break room"], a: 1, why: "1910.147(f)(1): temporary reactivation is tightly controlled." },
  { id: "lo-17", category: "loto", topic: "Contractors", q: "When contractors service equipment, the host and contractor must:", choices: ["Ignore each other’s programs", "Inform each other of their lockout procedures and coordinate", "Use only the contractor’s locks on host equipment with no communication", "Skip LOTO if the visit is short"], a: 1, why: "1910.147(f)(2): outside personnel. Conflicting programs cause start-ups on people." },
  { id: "lo-18", category: "loto", topic: "Normal production", q: "Minor tool changes and adjustments that are routine, repetitive, and integral to production may use:", choices: ["No protection", "Alternative measures that provide effective protection (1910.147(a)(2)(ii) note) — not an excuse to skip LOTO for true servicing", "Only a supervisor’s wave", "Removal of all guards"], a: 1, why: "The production exception is narrow. If you crawl into a machine or bypass a guard, you are in LOTO territory." },
  { id: "lo-19", category: "loto", topic: "Release", q: "Before removing locks and restoring energy:", choices: ["Tools and workers must be clear, guards replaced, and affected employees notified", "Start the machine to see who is left", "Remove the last person’s lock first while they are inside", "Skip notification"], a: 0, why: "1910.147(e): inspect the work area, notify, then remove your own lock." },
  { id: "lo-20", category: "loto", topic: "Training authorized", q: "Authorized employees must be trained on:", choices: ["Recognition of energy sources, type and magnitude, and methods of isolation and control", "Only the company mission statement", "How to cut locks", "Payroll"], a: 0, why: "1910.147(c)(7): authorized, affected, and other employees have different training depth." },
  { id: "lo-21", category: "loto", topic: "Retraining LOTO", q: "LOTO retraining is required when:", choices: ["There is a change in machines, processes, or energy-control procedures, or an inspection reveals gaps", "Never", "Only after 20 years", "Only for affected employees"], a: 0, why: "Also retrain when workers deviate from the procedure." },
  { id: "lo-22", category: "loto", topic: "Hasp", q: "A lockout hasp allows:", choices: ["One lock to lock 20 machines", "Multiple authorized employees to apply their own locks to one isolation point", "Tagout without locks always", "The supervisor to keep all keys"], a: 1, why: "Each person remains protected until they remove their own lock." },

  { id: "mh-16", category: "materials", topic: "Hand signals", q: "Crane hand signals must be:", choices: ["Made up daily", "Standard signals in 1926 Subpart CC unless a qualified signal person uses a documented non-standard system", "Optional if you shout", "Only used at night"], a: 1, why: "1926.1419–1422: qualified signal person when required. Radios must be dedicated and tested." },
  { id: "mh-17", category: "materials", topic: "Two blocking", q: "Two-blocking is:", choices: ["A legal lift method", "When the hook block hits the boom tip — it can break the line and drop the load", "A type of outrigger", "A signal"], a: 1, why: "Anti-two-block devices are required on many cranes. Never disable them." },
  { id: "mh-18", category: "materials", topic: "Wind", q: "High wind during a crane lift:", choices: ["Can require stopping the lift per manufacturer limits", "Improves capacity", "Only affects tower cranes", "Is ignored if you boom down"], a: 0, why: "Load charts and manuals list wind limits. Side load on the boom is dangerous." },
  { id: "mh-19", category: "materials", topic: "Critical lift", q: "A critical lift often includes:", choices: ["Any load under 50 lb", "Multiple cranes, near-capacity lifts, or lifts over occupied spaces — extra planning required", "Picking up a toolbox", "Forklift travel in a warehouse aisle"], a: 1, why: "Employers and ASME B30 practices require a lift plan. OSHA Subpart CC requires extra precautions for certain operations." },
  { id: "mh-20", category: "materials", topic: "Synthetic sling", q: "Synthetic web slings must not be:", choices: ["Protected from sharp edges", "Knotted, choked on a hook without a sling hook, or used if cut, UV-rotted, or melted", "Inspected", "Used within capacity"], a: 1, why: "1926.251: no knots. Edges cut webbing. Use wear pads." },
  { id: "mh-21", category: "materials", topic: "Wire rope sling", q: "Remove a wire-rope sling from service when:", choices: ["It looks shiny", "There is kinking, crushing, birdcaging, or broken-wire counts beyond the standard", "It has been used once", "The tag is still attached"], a: 1, why: "1926.251 and ASME B30.9: broken wire criteria depend on construction. Never use a sling as a choker if damaged." },
  { id: "mh-22", category: "materials", topic: "Forklift seatbelt", q: "On a sit-down counterbalanced forklift, the operator should:", choices: ["Wear the seat belt", "Never use a belt so they can jump", "Stand on the forks", "Raise the load to see better when traveling"], a: 0, why: "Tip-over: stay in the cab, lean away from the fall, belt on. Jumping is how people get crushed." },
  { id: "mh-23", category: "materials", topic: "Travel load", q: "Carry a forklift load:", choices: ["High and tilted back as far as possible always", "Low, with mast tilted back, and forks just high enough to clear the floor", "On the tips of the forks", "While someone rides the load"], a: 1, why: "Stability triangle. High loads tip. No riders on forks unless a designed personnel platform is used under the rules." },
  { id: "mh-24", category: "materials", topic: "Pedestrians", q: "In areas with pedestrians, forklift operators should:", choices: ["Horn at intersections, slow down, and never assume people hear them", "Drive at highway speed", "Raise the load to warn people", "Text while driving"], a: 0, why: "1910.178(n): traffic rules, horns, separate pedestrians when possible." },
  { id: "mh-25", category: "materials", topic: "Propane PIT", q: "LP-gas forklifts indoors:", choices: ["Have no ventilation issues", "Produce CO; need ventilation and maintenance of the fuel system", "Are banned always", "Can idle in a closed trailer for heat"], a: 1, why: "CO poisonings happen in trailers and coolers. Shut off fuel when parked as required." },
  { id: "mh-26", category: "materials", topic: "Grinder RPM", q: "An abrasive wheel’s RPM rating must be:", choices: ["Lower than the grinder speed so it spins faster", "At least as high as the machine’s speed", "Ignored on portable grinders", "Half the machine speed"], a: 1, why: "A wheel rated 6,000 RPM on a 10,000 RPM grinder can burst. Match ratings." },
  { id: "mh-27", category: "materials", topic: "Guards tools", q: "Power-tool guards:", choices: ["May be removed for a better view", "Must remain in place as designed", "Are optional after OSHA 10", "Apply only to table saws"], a: 1, why: "1926.300 / 1910.212: guards on. Removing a grinder guard is a common citation and injury." },

  { id: "hh-14", category: "health", topic: "Silica action", q: "The silica action level is an 8-hour TWA of:", choices: ["10 μg/m³", "25 μg/m³", "50 μg/m³", "100 μg/m³"], a: 1, why: "At or above 25 μg/m³, medical surveillance, hazard communication, and other program elements apply as specified." },
  { id: "hh-15", category: "health", topic: "Dry sweeping silica", q: "Dry sweeping or dry compressed-air blowing of silica dust is:", choices: ["The preferred method", "Generally prohibited where feasible alternatives exist (wet methods, HEPA vacuum)", "Required by Table 1", "Safe if you hold your breath"], a: 1, why: "1926.1153(f): housekeeping. Compressed air for cleaning is heavily restricted." },
  { id: "hh-16", category: "health", topic: "Lead medical", q: "Blood lead monitoring is part of:", choices: ["The lead standard when exposures reach action-level triggers", "Only childhood programs", "HazCom labels only", "Fire extinguisher inspections"], a: 0, why: "1926.62 / 1910.1025: medical surveillance, removal at specified blood-lead levels, and hygiene facilities." },
  { id: "hh-17", category: "health", topic: "Asbestos Class I", q: "Class I asbestos work is:", choices: ["Office paperwork", "Removal of TSI and surfacing ACM", "Floor tile only always", "Driving a truck"], a: 1, why: "1926.1101: Class I is the most hazardous removal. Class II is other ACM removal; Class III maintenance; Class IV cleanup of dust." },
  { id: "hh-18", category: "health", topic: "CO symptoms", q: "Early carbon monoxide symptoms often include:", choices: ["Bright green skin", "Headache, dizziness, nausea, and confusion", "Only a cough years later", "Improved athletic performance"], a: 1, why: "Get to fresh air. CO detectors on jobs using heaters and generators save lives." },
  { id: "hh-19", category: "health", topic: "Heat emergency", q: "For suspected heat stroke (hot, confused or unconscious, may stop sweating):", choices: ["Have them keep working in the shade", "Call 911, cool rapidly (ice, water, shade), and do not delay", "Give salt tablets only", "Wait an hour to see"], a: 1, why: "Heat stroke is a medical emergency. Cooling while waiting for EMS is critical." },
  { id: "hh-20", category: "health", topic: "WBGT", q: "Heat programs often use:", choices: ["Wind chill only", "Wet Bulb Globe Temperature (WBGT) or heat index plus work/rest cycles", "Only air temperature in the sun ignored", "Noise dosimeters"], a: 1, why: "NIOSH/OSHA heat guidance uses WBGT. ACGIH TLVs set work/rest by workload." },
  { id: "hh-21", category: "health", topic: "Cold wind", q: "Wind chill increases:", choices: ["Heat stress", "The rate of heat loss and frostbite risk", "Silica exposure", "GFCI trip time"], a: 1, why: "Cover skin, stay dry, take warm-up breaks. Frostbite can happen above 0°F with wind and wetness." },
  { id: "hh-22", category: "health", topic: "Hex chrome PEL", q: "The hexavalent chromium PEL is an 8-hour TWA of:", choices: ["5 μg/m³", "50 μg/m³", "500 μg/m³", "5 mg/m³"], a: 0, why: "1910.1026: 5 μg/m³. Stainless welding fume is a common construction/GI source." },
  { id: "hh-23", category: "health", topic: "Welding hex", q: "To reduce hex chrome in stainless welding:", choices: ["Weld in a closed tank with no exhaust", "Local exhaust ventilation, process change, and respirators as required", "Only a paper mask worn on the chin", "More argon always eliminates hex"], a: 1, why: "LEV at the plume plus respiratory protection when needed. Coatings on steel can be worse than the base metal." },
  { id: "hh-24", category: "health", topic: "Benzene", q: "Benzene is:", choices: ["A carcinogen associated with gasoline, solvents, and some petrochemical work", "A vitamin", "Only a dust", "Harmless if it smells sweet"], a: 0, why: "1910.1028: strict PELs, medical, and hygiene. Do not wash hands in gasoline." },
  { id: "hh-25", category: "health", topic: "Hearing audiogram", q: "A baseline audiogram in a hearing conservation program is generally obtained:", choices: ["Within 6 months of first exposure at or above the action level (1 year if using mobile vans, with hearing protection in the interim)", "After 10 years", "Never", "Only if the worker complains"], a: 0, why: "1910.95: baseline then annual audiograms. STS (standard threshold shift) triggers follow-up." },
  { id: "hh-26", category: "health", topic: "Lead hygiene", q: "In lead work areas, workers must not:", choices: ["Eat, drink, or use tobacco in the contaminated area", "Wash hands", "Wear protective clothing", "Use hygiene facilities"], a: 0, why: "1926.62: change areas, showers when triggered, and no food in the work area to prevent ingestion." },

  { id: "fr-11", category: "fire", topic: "Class D", q: "Class D fires involve:", choices: ["Paper", "Combustible metals such as magnesium or titanium", "Energized panels only", "Cooking oil"], a: 1, why: "Use a Class D powder rated for that metal. Water can make metal fires worse." },
  { id: "fr-12", category: "fire", topic: "Class K", q: "Class K extinguishers are for:", choices: ["Wood pallets", "Commercial cooking oils and fats", "Gasoline only", "Electrical rooms only"], a: 1, why: "Wet chemical Class K for fryers. Do not use a Class B dry chemical as the kitchen’s only plan if K is required." },
  { id: "fr-13", category: "fire", topic: "Class B distance", q: "Maximum travel distance to a Class B extinguisher is generally:", choices: ["25 feet", "50 feet", "75 feet", "150 feet"], a: 1, why: "1910.157(d)(4): 50 feet for Class B." },
  { id: "fr-14", category: "fire", topic: "Fire watch time", q: "After welding or cutting where a fire watch is required, the watch should last at least:", choices: ["5 minutes", "30 minutes (and longer if needed for smoldering)", "2 hours always", "Until the welder leaves the parking lot"], a: 1, why: "1910.252(a)(2)(iii): at least 30 minutes. Some operations need longer." },
  { id: "fr-15", category: "fire", topic: "Flammable cabinet", q: "Approved flammable storage cabinets:", choices: ["Are designed to protect contents from a fire outside for a period of time", "Make liquids non-flammable", "Replace grounding of drums", "Can be left open with the door off"], a: 0, why: "1910.106: limits on quantities outside cabinets. Keep doors closed. Grounding/bonding still matter when dispensing." },
  { id: "fr-16", category: "fire", topic: "Flash point", q: "A flammable liquid (Category 1–2 style / older Class I) has a flash point:", choices: ["Generally below 100°F for Class I under the older OSHA definition", "Always above 200°F", "Of 0 K only", "That does not matter for storage"], a: 0, why: "1910.106 uses flash point and boiling point. GHS categories differ slightly; the hazard is still fire." },
  { id: "fr-17", category: "fire", topic: "Exit discharge", q: "An exit discharge must:", choices: ["Lead to a street, walkway, or open space with access to the outside", "End in a locked courtyard with no way out", "Go through a storage room of combustibles as the only path", "Be used for pallet storage"], a: 0, why: "1910.34–37: the exit path stays an exit until you are safely outside." },
  { id: "fr-18", category: "fire", topic: "Alarm", q: "Employee alarm systems must be:", choices: ["Distinctive and recognizable as a signal to evacuate or take action", "The same as the break bell if convenient", "Optional under 500 people always", "Text-only"], a: 0, why: "1910.165 / 1910.38: everyone must know the alarm. Test the system." },
  { id: "fr-19", category: "fire", topic: "Sprinklers", q: "Material storage must be kept:", choices: ["Stacked against sprinkler heads", "At least 18 inches below sprinkler deflectors (more for some extra-high storage rules)", "Touching heaters", "In front of extinguishers"], a: 1, why: "1910.159 and NFPA: clearance so water can spray. Do not hang clothes on sprinkler piping." },
  { id: "fr-20", category: "fire", topic: "Oily rags", q: "Oil- and solvent-soaked rags should be:", choices: ["Piled in a corner", "Placed in covered metal containers to prevent spontaneous combustion", "Left in a worker’s pocket", "Tossed with paper recyclables"], a: 1, why: "Linseed oil and some finishes heat as they dry. Use listed oily-waste cans." },

  { id: "ww-08", category: "walking", topic: "Load rating", q: "Walking-working surfaces must be able to support:", choices: ["The maximum intended load", "Only the weight of one person always", "Snow only", "Half the intended load"], a: 0, why: "1910.22(b): surfaces, including covers and gratings, must support the load. Scaffold and floor-hole covers have extra factors." },
  { id: "ww-09", category: "walking", topic: "Dockboards", q: "Dockboards (bridge plates) must be:", choices: ["Secured to prevent slipping and able to support the load", "Made of cardboard", "Optional if the gap is 2 feet", "Used as a see-saw"], a: 0, why: "1910.30 / 1910.26: portable and powered dockboards have specific rules including prevention of run-off." },
  { id: "ww-10", category: "walking", topic: "Ladders GI", q: "In general industry, portable ladder use includes:", choices: ["Facing the ladder, three-point contact, and not carrying loads that cause a fall", "Standing on the top cap of a stepladder", "Using a metal ladder next to live bus bars", "Splicing two ladders with wire"], a: 0, why: "1910.23: similar principles to construction 1926.1053." },
  { id: "ww-11", category: "walking", topic: "Stair nosing", q: "Standard stairs should have:", choices: ["Uniform riser height and tread depth; nosing that does not create a trip", "Random riser heights to slow people down", "Open 20-inch gaps between treads", "No handrail if used by contractors"], a: 0, why: "1910.25: specified angles (typically 30–50 degrees), uniformity, and railings." },
  { id: "ww-12", category: "walking", topic: "Rope descent", q: "Rope descent systems in GI (window washing) generally require:", choices: ["No training", "Training, inspected equipment, independent backup, and building owner documentation of anchorages", "A single uninspected rope", "Body belts for arrest"], a: 1, why: "1910.27: RDS rules after several fatalities. Anchors must be certified." },
  { id: "ww-13", category: "walking", topic: "Wet floors", q: "When floors are wet:", choices: ["Warn, clean, use mats, and provide drainage where required", "Turn off the lights", "Run", "Store extra pallets in the puddle"], a: 0, why: "1910.22(a)(2): keep as dry as possible; use drainage, platforms, mats, or false floors." },
  { id: "ww-14", category: "walking", topic: "Ladder cage GI", q: "Fixed ladders in general industry installed on or after November 19, 2018, generally must have:", choices: ["Cages as the only allowed system forever", "Ladder safety systems or personal fall arrest instead of cages for heights over 24 feet, with a phase-in for older ladders", "No protection", "Only a rest platform at 100 feet"], a: 1, why: "1910.28(b)(9): cages are being phased out as the primary system on fixed ladders." },
  { id: "ww-15", category: "walking", topic: "Housekeeping construction", q: "Construction debris must be:", choices: ["Cleared at regular intervals so it does not accumulate and cause hazards", "Left until the Certificate of Occupancy", "Pushed into stairwells", "Burned in the building"], a: 0, why: "1926.25: form and scrap lumber with protruding nails kept cleared; containers for waste." },

  { id: "cs-01", category: "confined", topic: "Definition", q: "A confined space is a space that:", choices: ["Is large enough to enter, has limited entry/exit, and is not designed for continuous occupancy", "Is any room with a door", "Is only underground", "Is any excavation"], a: 0, why: "1910.146(b): all three criteria. Construction uses 1926 Subpart AA with similar concepts." },
  { id: "cs-02", category: "confined", topic: "Permit-required", q: "A permit-required confined space has one or more of:", choices: ["Hazardous atmosphere, engulfment, inwardly converging walls/floors, or any other serious safety/health hazard", "Good lighting and two doors", "A window", "Only dust that is not combustible"], a: 0, why: "PRCS needs a written program, permits, attendants, and rescue planning." },
  { id: "cs-03", category: "confined", topic: "Oxygen", q: "Acceptable oxygen for entry is generally:", choices: ["16.0% to 18.0%", "19.5% to 23.5%", "25% to 30%", "Any level if you feel fine"], a: 1, why: "Below 19.5% is oxygen deficient. Above 23.5% is oxygen enriched and a fire hazard." },
  { id: "cs-04", category: "confined", topic: "Test order", q: "Atmospheric testing order is typically:", choices: ["Toxics, then oxygen, then flammables", "Oxygen, then flammable/explosive, then toxic gases", "Only flammables", "Whatever the meter does first by accident"], a: 1, why: "1910.146(c)(5)(ii)(C) note: O2 first (meters need O2 to read LEL correctly), then LEL, then toxics." },
  { id: "cs-05", category: "confined", topic: "LEL", q: "Entry is generally not allowed if flammable gas is at or above:", choices: ["1% of the LEL", "10% of the LEL (for permit spaces unless a specific exception applies)", "100% LEL", "The UEL only"], a: 1, why: "1910.146(b) hazardous atmosphere includes flammable gas over 10% of LEL. Some industries use stricter limits." },
  { id: "cs-06", category: "confined", topic: "Attendant", q: "The attendant’s job is to:", choices: ["Enter to help with tools", "Stay outside, monitor entrants, keep unauthorized people out, and summon rescue — not to enter for rescue unless trained, relieved, and equipped", "Leave if it is slow", "Operate the process from inside"], a: 1, why: "Never abandon the watch. Multiple spaces need procedures if one attendant covers more than one." },
  { id: "cs-07", category: "confined", topic: "Entrant", q: "Authorized entrants must:", choices: ["Ignore the permit", "Know the hazards, use equipment, communicate with the attendant, and exit when told or when they notice a problem", "Remove their harness for comfort", "Test the atmosphere only after they feel dizzy"], a: 1, why: "1910.146(h): duties of authorized entrants." },
  { id: "cs-08", category: "confined", topic: "Supervisor", q: "The entry supervisor:", choices: ["Signs the permit, verifies tests and rescue, and may also serve as attendant or entrant if qualified", "Is only a job title on an org chart", "Never visits the space", "Can skip atmospheric tests"], a: 0, why: "1910.146(j): the supervisor authorizes entry and terminates it when conditions change." },
  { id: "cs-09", category: "confined", topic: "Rescue", q: "The preferred rescue method is:", choices: ["Untrained coworkers rushing in", "Non-entry rescue (retrieval line) whenever it will not increase the risk", "Waiting to see if they wake up", "Filling the space with oxygen"], a: 1, why: "Most confined-space deaths are would-be rescuers. Retrieval winches and harnesses save lives when vertical spaces allow." },
  { id: "cs-10", category: "confined", topic: "Host employer", q: "When a contractor enters a host’s permit space, the host must:", choices: ["Say nothing about hazards", "Inform the contractor of the permit program, hazards, and any precautions", "Cancel all permits", "Provide no information for liability reasons"], a: 1, why: "1910.146(c)(8) and (c)(9): host and contractor duties both ways after the job." },
  { id: "cs-11", category: "confined", topic: "Reclassify", q: "A permit space may be reclassified as non-permit only when:", choices: ["You post a sign that says so", "All actual or potential hazards are eliminated without needing continuous forced air (isolation, etc.) as specified", "Oxygen is 20.8% once", "A fan is placed at the opening without evaluation"], a: 1, why: "1910.146(c)(7): reclassification is documented and lasts only as long as hazards stay eliminated. Forced-air ventilation alone does not reclassify; it can allow alternate entry under (c)(5)." },
  { id: "cs-12", category: "confined", topic: "Alternate entry", q: "Alternate entry procedures (c)(5) apply when:", choices: ["The only hazard is actual or potential hazardous atmosphere and continuous forced air plus tests keep it safe", "There is an engulfment hazard", "There are inwardly sloping floors that can trap", "You are in a hurry"], a: 0, why: "If engulfment or configuration hazards exist, you need the full permit program." },
  { id: "cs-13", category: "confined", topic: "Ventilation", q: "Forced-air ventilation for alternate entry must:", choices: ["Be directed to ventilate the immediate areas where employees are and continue until they leave", "Blow from the bottom of a deep pit without a plan", "Use pure oxygen", "Run only 30 seconds before entry"], a: 0, why: "1910.146(c)(5): ventilate, test, and keep air moving from a clean source." },
  { id: "cs-14", category: "confined", topic: "Isolation", q: "Isolation of a permit space can include:", choices: ["Blanking/blinding, misaligning pipes, double block and bleed, and lockout of energy", "A cone in front of the hatch", "Asking operators not to start pumps", "A paper sign on a valve"], a: 0, why: "1910.146(b) defines isolation. LOTO of mixers and conveyors is part of many entries." },
  { id: "cs-15", category: "confined", topic: "Signs", q: "Permit spaces that are not entered must still be:", choices: ["Hidden", "Identified by danger signs or other equally effective means", "Filled with water", "Left open for airflow"], a: 1, why: "1910.146(c)(2): DANGER — PERMIT-REQUIRED CONFINED SPACE — DO NOT ENTER or equivalent." },
  { id: "cs-16", category: "confined", topic: "Construction AA", q: "Construction confined spaces are covered by:", choices: ["Only 1910.146 on every job", "29 CFR 1926 Subpart AA", "No standard", "Only state building codes"], a: 1, why: "Subpart AA (1926.1201–1213) is the construction rule. It is similar to 1910.146 with construction-specific host/controlling contractor duties." },
  { id: "cs-17", category: "confined", topic: "H2S", q: "Hydrogen sulfide in sewers and tanks is dangerous because it:", choices: ["Smells like flowers at high concentrations", "Can paralyze smell at higher concentrations and is highly toxic and flammable", "Is harmless", "Is lighter than air always so it never collects"], a: 1, why: "H2S is heavier than air and can pool. Do not trust your nose. Use a meter." },
  { id: "cs-18", category: "confined", topic: "Engulfment", q: "Grain, sand, or water in a silo or pit is an:", choices: ["Engulfment hazard", "Only a slip hazard", "Electrical hazard only", "Fall hazard only"], a: 0, why: "Flowing material can bury and asphyxiate. Lockout of unloaders and use of harnesses/retrieval as required." },
  { id: "cs-19", category: "confined", topic: "Training CS", q: "Confined-space training is required:", choices: ["Before assigned duties and when hazards or duties change", "Once in a lifetime", "Only for rescue teams", "Only if a fatality occurred"], a: 0, why: "1910.146(g): train, and document that training occurred." },
  { id: "cs-20", category: "confined", topic: "Permit duration", q: "An entry permit must be:", choices: ["Kept until entry is complete, then retained for at least 1 year", "Thrown away immediately", "Valid for 5 years of entries", "Verbal only"], a: 0, why: "1910.146(e)(6) and (f): cancel the permit when done; review canceled permits within 1 year to update the program." },
  { id: "cs-21", category: "confined", topic: "Early symptoms", q: "If an entrant feels dizzy or the meter alarms:", choices: ["Finish the last five minutes of work", "Evacuate immediately", "Turn the meter off", "Send the attendant in"], a: 1, why: "Exit on alarm, on order, or on any symptom. Re-evaluate before anyone goes back." },
  { id: "cs-22", category: "confined", topic: "Retrieval", q: "Chest or full-body harness with a retrieval line is required unless:", choices: ["It would increase the overall risk or would not help rescue (for example, some horizontal piping)", "The worker dislikes harnesses", "The space is permit-required", "The attendant has a cell phone"], a: 0, why: "1910.146(k)(3): non-entry rescue equipment is the default. Document exceptions." },
  { id: "cs-23", category: "confined", topic: "Rescue team", q: "An off-site rescue service must be:", choices: ["The fire department that has never trained on your spaces and is 45 minutes away, without evaluation", "Evaluated for ability to respond in time and practice with your types of spaces", "Optional if you have a permit", "Only a tow-truck company"], a: 1, why: "1910.146(k): evaluate rescue. Invite them to practice. Time to patient matters — brain damage starts in minutes." },
  { id: "cs-24", category: "confined", topic: "Hot work CS", q: "Welding in a confined space requires:", choices: ["No extra rules", "Hot-work precautions plus confined-space atmospheric controls; never use oxygen to ventilate", "Pure oxygen to “sweeten” the air", "Closing all vents"], a: 1, why: "1910.252 and 1910.146 overlap. Inerting, fire watch, and gas isolation are common." },
  { id: "cs-25", category: "confined", topic: "Would-be rescuers", q: "The majority of confined-space fatalities are often:", choices: ["Trained rescue teams with SCBAs", "Untrained would-be rescuers who enter after the first victim", "Office workers", "People using retrieval winches correctly"], a: 1, why: "Do not enter to save someone unless you are the designated, equipped rescue team and another attendant is in place." }
];
